package com.gerenciadorrural.modules.herd.api;
import com.gerenciadorrural.modules.herd.application.*; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/herd/paddocks") public class PaddockMovementLogController {private final TenantMovementLog log;public PaddockMovementLogController(TenantMovementLog log){this.log=log;}@GetMapping("/{id}/movements") public ResponseEntity<Response> get(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestParam(required=false) Integer page,@RequestParam(required=false) Integer size,HttpServletRequest r){if(!Set.of("page","size").containsAll(r.getParameterMap().keySet())||r.getParameterMap().values().stream().anyMatch(v->v.length!=1))throw new HerdAnimalQueryException();var x=log.execute(c,id,page==null?0:page,size==null?20:size);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Response.from(x));}public record Response(List<Item> items,int page,int size,long totalElements,int totalPages){static Response from(TenantMovementLog.Result x){return new Response(x.items().stream().map(Item::from).toList(),x.page(),x.size(),x.totalElements(),x.totalPages());}}public record Item(String eventId,String animalId,String identification,String sourcePaddockId,String sourcePaddockName,String destinationPaddockId,String destinationPaddockName,LocalDate occurredOn,Instant recordedAt,String actorUserId){static Item from(PaddockMovement x){return new Item(x.eventId().toString(),x.animalId().toString(),x.identification(),x.sourcePaddockId()==null?null:x.sourcePaddockId().toString(),x.sourcePaddockName(),x.destinationPaddockId().toString(),x.destinationPaddockName(),x.occurredOn(),x.recordedAt(),x.actorUserId()==null?null:x.actorUserId().toString());}}}
